    <tr style="border-bottom: 1px solid #E2E8F0;">
      <td style="padding: 12px 0;">${T.name}</td>
      <td style="padding: 12px 0; text-align: center;">${T.quantity}</td>
      <td style="padding: 12px 0; text-align: right;">R$ ${T.price.toFixed(2).replace(".",",")}</td>
      <td style="padding: 12px 0; text-align: right; font-weight: bold;">R$ ${(T.price*T.quantity).toFixed(2).replace(".",",")}</td>
    </tr>
